  1	package cli
  2	
  3	import (
  4		"context"
  5		"encoding/json"
  6		"errors"
  7		"fmt"
  8		"io"
  9		"sort"
 10		"strings"
 11	
 12		"github.com/entireio/entire-graph/internal/sem"
 13		"github.com/entireio/entire-graph/internal/termsafe"
 14	)
 15	
 16	// gate — which tests does this change need, and what does no test reach?
 17	//
 18	// The command is the thin shell around sem.Gate: it resolves the repository and the change range,
 19	// builds one snapshot, hands both to the engine, and renders the answer. All judgement lives in
 20	// package sem, so this file stays about argument handling and presentation.
 21	
 22	const (
 23		gateDefaultFormat = "text"
 24		// Default to the full profile rather than search's "fast". Only the full profile emits TESTS
 25		// edges (provider.go:6226), and quietly dropping one of the three evidence routes would make
 26		// the UNCOVERED verdict — the entire point of the command — less trustworthy without saying so.
 27		gateDefaultProfile = "full"
 28	)
 29	
 30	type gateFlags struct {
 31		Repo         string
 32		Base         string
 33		Head         string
 34		Checkpoint   string
 35		Format       string
 36		Profile      string
 37		Depth        int
 38		CacheDir     string
 39		DisableCache bool
 40	}
 41	
 42	func parseGateFlags(args []string) (gateFlags, error) {
 43		flags := gateFlags{
 44			Base:    "main",
 45			Head:    "HEAD",
 46			Format:  gateDefaultFormat,
 47			Profile: gateDefaultProfile,
 48		}
 49		for index := 0; index < len(args); index++ {
 50			arg := args[index]
 51			value := func() (string, error) {
 52				index++
 53				if index >= len(args) {
 54					return "", fmt.Errorf("%s requires a value", arg)
 55				}
 56				return args[index], nil
 57			}
 58			var err error
 59			switch arg {
 60			case "--repo":
 61				flags.Repo, err = value()
 62			case "--base":
 63				flags.Base, err = value()
 64			case "--head":
 65				flags.Head, err = value()
 66			case "--checkpoint":
 67				flags.Checkpoint, err = value()
 68			case "--format":
 69				flags.Format, err = value()
 70			case "--profile":
 71				flags.Profile, err = value()
 72			case "--cache-dir":
 73				flags.CacheDir, err = value()
 74			case "--no-cache":
 75				flags.DisableCache = true
 76			case "--depth":
 77				parsed, next, parseErr := searchPositiveIntFlag(args, index)
 78				if parseErr != nil {
 79					return flags, parseErr
 80				}
 81				flags.Depth, index = parsed, next
 82			default:
 83				return flags, fmt.Errorf("gate received unexpected argument %q", arg)
 84			}
 85			if err != nil {
 86				return flags, err
 87			}
 88		}
 89	
 90		// A checkpoint already names its own range: it resolves to one commit and its first parent.
 91		// Accepting an explicit range alongside it would let the two disagree with no way to tell
 92		// which the output described.
 93		if flags.Checkpoint != "" {
 94			for _, pair := range []struct{ name, value, standard string }{
 95				{"--base", flags.Base, "main"},
 96				{"--head", flags.Head, "HEAD"},
 97			} {
 98				if pair.value != pair.standard {
 99					return flags, fmt.Errorf("gate --checkpoint cannot be combined with %s", pair.name)
100				}
101			}
102		}
103		if flags.Format != "text" && flags.Format != "json" {
104			return flags, fmt.Errorf("gate --format must be text or json, got %q", flags.Format)
105		}
106		if flags.Depth != 0 && flags.Depth != 1 && flags.Depth != 2 {
107			return flags, errors.New("gate --depth must be 1 or 2")
108		}
109		return flags, nil
110	}
111	
112	func runGate(ctx context.Context, opts Options, args []string) error {
113		flags, err := parseGateFlags(args)
114		if err != nil {
115			return err
116		}
117		profile, err := parseProfile(flags.Profile)
118		if err != nil {
119			return err
120		}
121		repo, err := resolveRepo(ctx, opts.Env, flags.Repo)
122		if err != nil {
123			return err
124		}
125		if err := sem.EnsureGitMetadataSafeForSubprocess(repo); err != nil {
126			return err
127		}
128	
129		var change sem.Result
130		if flags.Checkpoint != "" {
131			change, err = sem.AnalyzeCheckpoint(ctx, repo, flags.Checkpoint)
132		} else {
133			// Both revisions are spliced into a git argv, so a value that begins with "-" would stop
134			// being a revision and become a flag of the command it lands in. validateRevision is the
135			// existing guard for that (root.go:838, CWE-88).
136			if err := validateRevision("gate --base", flags.Base); err != nil {
137				return err
138			}
139			if err := validateRevision("gate --head", flags.Head); err != nil {
140				return err
141			}
142			change, err = sem.AnalyzeGitRange(ctx, repo, flags.Base, flags.Head, nil)
143		}
144		if err != nil {
145			return err
146		}
147	
148		snapshot, _, err := sem.LoadOrBuildProviderSnapshot(ctx, repo, opts.Version, sem.ProviderSnapshotOptions{
149			NoNetwork: true,
150			Profile:   profile,
151		}, resolveCacheDir(flags.CacheDir, opts.Env.PluginDataDir), flags.DisableCache)
152		if err != nil {
153			return err
154		}
155	
156		result := sem.Gate(change, snapshot, sem.GateOptions{Depth: flags.Depth})
157	
158		if flags.Format == "json" {
159			encoder := json.NewEncoder(termsafe.NewJSONWriter(opts.Stdout))
160			encoder.SetEscapeHTML(false)
161			return encoder.Encode(result)
162		}
163		writeGateText(opts.Stdout, result)
164		return nil
165	}
166	
167	// gateGoTestCommand composes one command covering the whole selection.
168	//
169	// The existing emitter names a single test (deriveSearchVerifyGo, search_verify.go:919). A change
170	// set selects a set, so the pattern is an alternation over every selected name, sorted so the same
171	// selection always renders the same command.
172	//
173	// Names go test cannot run are dropped rather than emitted: `-run` only matches functions named
174	// Test*, so including anything else would produce a command that silently selects nothing — and a
175	// green run of nothing reads exactly like a green run of everything. When nothing runnable is
176	// left, no command is emitted at all. Falling back to the whole suite would answer a question the
177	// caller did not ask; "run everything" is the state they were already in.
178	func gateGoTestCommand(tests []sem.GateSelectedTest) string {
179		seen := map[string]bool{}
180		names := make([]string, 0, len(tests))
181		for _, test := range tests {
182			if !strings.HasPrefix(test.Name, "Test") || seen[test.Name] {
183				continue
184			}
185			seen[test.Name] = true
186			names = append(names, test.Name)
187		}
188		if len(names) == 0 {
189			return ""
190		}
191		sort.Strings(names)
192		return "go test -run '^(" + strings.Join(names, "|") + ")$' ./..."
193	}
194	
195	// gateAllSelectedTests flattens every per-symbol selection into one set for the command.
196	func gateAllSelectedTests(result sem.GateResult) []sem.GateSelectedTest {
197		var all []sem.GateSelectedTest
198		for _, changed := range result.Changed {
199			all = append(all, changed.Tests...)
200		}
201		return all
202	}
203	
204	func writeGateText(out io.Writer, result sem.GateResult) {
205		out = termsafe.NewWriter(out)
206	
207		scope := result.Base + " -> " + result.Head
208		if result.Checkpoint != "" {
209			scope = "checkpoint " + result.Checkpoint
210		}
211		fmt.Fprintf(out, "CHANGED  %d symbols   (%s)\n", len(result.Changed), termsafe.Line(scope))
212	
213		if !result.TestsRelationAvailable {
214			fmt.Fprintf(out, "  note: this snapshot carries no TESTS relation (profile %s); "+
215				"attribution used call edges and naming conventions only\n", termsafe.Line(result.Profile))
216		}
217	
218		for _, changed := range result.Changed {
219			fmt.Fprintf(out, "\n%-9s %s   %s:%d\n",
220				changed.Verdict, termsafe.Line(changed.Name), termsafe.Line(changed.FilePath), changed.StartLine)
221			fmt.Fprintf(out, "  dependents: %d\n", changed.Dependents)
222	
223			for _, test := range changed.Tests {
224				fmt.Fprintf(out, "  selected:   %s   %s:%d  (%s, depth %d)\n",
225					termsafe.Line(test.Name), termsafe.Line(test.FilePath), test.StartLine,
226					termsafe.Line(test.Route), test.Depth)
227				if len(test.Chain) > 1 {
228					fmt.Fprintf(out, "  evidence:   %s\n", termsafe.Line(strings.Join(test.Chain, " -> ")))
229				}
230			}
231			if changed.Verdict == sem.GateUncovered {
232				// The whole reason the command exists. Said plainly, and scoped honestly: the graph
233				// cannot see calls made through interfaces, reflection or generated code, so this is
234				// a prompt to check rather than proof that nothing tests the symbol.
235				fmt.Fprintf(out, "  ! %d dependents and no test reaches this (no path the graph can see)\n",
236					changed.Dependents)
237			}
238			if changed.Truncated {
239				fmt.Fprint(out, "  ! fan-out cap reached; the selection above may be incomplete\n")
240			}
241		}
242	
243		if len(result.Unresolved) > 0 {
244			fmt.Fprint(out, "\nUNRESOLVED\n")
245			for _, unresolved := range result.Unresolved {
246				fmt.Fprintf(out, "  %s   %s   (%s)\n",
247					termsafe.Line(unresolved.Name), termsafe.Line(unresolved.Path), termsafe.Line(unresolved.Reason))
248			}
249		}
250	
251		if command := gateGoTestCommand(gateAllSelectedTests(result)); command != "" {
252			fmt.Fprintf(out, "\nVERIFY: %s\n", termsafe.Line(command))
253		}
254	}

